SELECT COUNT(*) AS total_reviews,
SUM(CASE WHEN lower(title) LIKE '%break out%' OR lower(text) LIKE '%break out%' OR lower(title) LIKE '%irrit%' OR lower(text) LIKE '%irrit%' OR lower(title) LIKE '%burn%' OR lower(text) LIKE '%burn%' OR lower(title) LIKE '%rash%' OR lower(text) LIKE '%rash%' OR lower(title) LIKE '%itch%' OR lower(text) LIKE '%itch%' OR lower(title) LIKE '%allerg%' OR lower(text) LIKE '%allerg%' OR lower(title) LIKE '%redness%' OR lower(text) LIKE '%redness%' THEN 1 ELSE 0 END) AS possible_skin_issue_reviews
FROM reviews;

